  4	public final class QuickSort {
  5	    private static final int INSERTION_SORT_THRESHOLD = 16;
  6	
  7	    private QuickSort() {
  8	        // Utility class.
  9	    }
 10	
 11	    public static void sort(int[] values) {
 12	        Objects.requireNonNull(values, "values");
 13	        sortRange(values, 0, values.length);
 14	    }
 15	
 16	    public static void sort(int[] values, int fromIndex, int toIndexExclusive) {
 17	        Objects.requireNonNull(values, "values");
 18	        sortRange(values, fromIndex, toIndexExclusive);
 19	    }
 20	
 21	    public static int[] sortedCopy(int[] values) {
 22	        Objects.requireNonNull(values, "values");
 23	        int[] copy = Arrays.copyOf(values, values.length);
 24	        sort(copy);
 25	        return copy;
 26	    }
 27	
 28	    private static void sortRange(int[] values, int fromIndex, int toIndexExclusive) {
 29	        Objects.checkFromToIndex(fromIndex, toIndexExclusive, values.length);
 30	        if (toIndexExclusive - fromIndex < 2) {
 31	            return;
 32	        }
 33	
 34	        quickSort(values, fromIndex, toIndexExclusive);
 35	    }
 36	
 37	    private static void quickSort(int[] values, int left, int rightExclusive) {
 38	        RangeStack pendingRanges = new RangeStack();
 39	        pendingRanges.push(left, rightExclusive);
 40	
 41	        while (pendingRanges.hasPendingRanges()) {
 42	            Range range = pendingRanges.pop();
 43	            left = range.left();
 44	            rightExclusive = range.rightExclusive();
 45	
 46	            while (rightExclusive - left > INSERTION_SORT_THRESHOLD) {
 47	                Partition partition = partition(values, left, rightExclusive);
 48	                Range lessThanRange = new Range(left, partition.lessThanEndExclusive());
 49	                Range greaterThanRange = new Range(partition.greaterThanStart(), rightExclusive);
 50	
 51	                if (lessThanRange.length() < greaterThanRange.length()) {
 52	                    if (greaterThanRange.length() > 1) {
 53	                        pendingRanges.push(greaterThanRange.left(), greaterThanRange.rightExclusive());
 54	                    }
 55	                    rightExclusive = lessThanRange.rightExclusive();
 56	                } else {
 57	                    if (lessThanRange.length() > 1) {
 58	                        pendingRanges.push(lessThanRange.left(), lessThanRange.rightExclusive());
 59	                    }
 60	                    left = greaterThanRange.left();
 61	                }
 62	            }
 63	
 64	            insertionSort(values, left, rightExclusive);
 65	        }
 66	    }
 67	
 68	    private static Partition partition(int[] values, int left, int rightExclusive) {
 69	        int pivot = choosePivotValue(values, left, rightExclusive);
 70	        int lessThan = left;
 71	        int index = left;
 72	        int greaterThan = rightExclusive - 1;
 73	
 74	        while (index <= greaterThan) {
 75	            int current = values[index];
 76	            if (current < pivot) {
 77	                swap(values, lessThan, index);
 78	                lessThan++;
 79	                index++;
 80	            } else if (current > pivot) {
 81	                swap(values, index, greaterThan);
 82	                greaterThan--;
 83	            } else {
 84	                index++;
 85	            }
 86	        }
 87	
 88	        return new Partition(lessThan, greaterThan + 1);
 89	    }
 90	
 91	    private static int choosePivotValue(int[] values, int left, int rightExclusive) {
 92	        int middle = left + ((rightExclusive - left - 1) >>> 1);
 93	        int right = rightExclusive - 1;
 94	
 95	        int leftValue = values[left];
 96	        int middleValue = values[middle];
 97	        int rightValue = values[right];
 98	
 99	        if (leftValue < middleValue) {
100	            if (middleValue < rightValue) {
101	                return middleValue;
102	            }
103	            return Math.max(leftValue, rightValue);
104	        }
105	
106	        if (leftValue < rightValue) {
107	            return leftValue;
108	        }
109	
110	        return Math.max(middleValue, rightValue);
111	    }
112	
113	    private static void insertionSort(int[] values, int left, int rightExclusive) {
114	        for (int index = left + 1; index < rightExclusive; index++) {
115	            int currentValue = values[index];
116	            int position = index - 1;
117	
118	            while (position >= left && values[position] > currentValue) {
119	                values[position + 1] = values[position];
120	                position--;
121	            }
122	
123	            values[position + 1] = currentValue;
124	        }
125	    }
126	
127	    private static void swap(int[] values, int first, int second) {
128	        int temp = values[first];
129	        values[first] = values[second];
130	        values[second] = temp;
131	    }
132	
133	    private record Partition(int lessThanEndExclusive, int greaterThanStart) {}
134	
135	    private record Range(int left, int rightExclusive) {
136	        private int length() {
137	            return rightExclusive - left;
138	        }
139	    }
140	
141	    private static final class RangeStack {
142	        private int[] lefts = new int[16];
143	        private int[] rights = new int[16];
144	        private int size;
145	
146	        private void push(int left, int rightExclusive) {
147	            ensureCapacity();
148	            lefts[size] = left;
149	            rights[size] = rightExclusive;
150	            size++;
151	        }
152	
153	        private Range pop() {
154	            size--;
155	            return new Range(lefts[size], rights[size]);
156	        }
157	
158	        private boolean hasPendingRanges() {
159	            return size > 0;
160	        }
161	
162	        private void ensureCapacity() {
163	            if (size < lefts.length) {
164	                return;
165	            }
166	
167	            lefts = Arrays.copyOf(lefts, lefts.length << 1);
168	            rights = Arrays.copyOf(rights, rights.length << 1);
169	        }
170	    }
171	}

